# Test flood-fill from edges theory

def flood_fill_boundary(grid):
    """Mark cells reachable from any edge boundary using non-2 values only"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    queue = []

    # Add all edge cells that are not 2
    for i in range(rows):
        if grid[i][0] != 2:
            queue.append((i, 0))
            visited[i][0] = True
        if grid[i][cols-1] != 2:
            queue.append((i, cols-1))
            visited[i][cols-1] = True
    for j in range(cols):
        if grid[0][j] != 2:
            queue.append((0, j))
            visited[0][j] = True
        if grid[rows-1][j] != 2:
            queue.append((rows-1, j))
            visited[rows-1][j] = True

    # BFS
    import collections
    q = collections.deque(queue)
    while q:
        i, j = q.popleft()
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj] and grid[ni][nj] != 2:
                visited[ni][nj] = True
                q.append((ni, nj))

    return visited

